<script setup lang="ts">
import { date } from '../lib/ui'
export interface Outreach {id:string;kind:string;status:string;reason:string;body:string;created_at:number;due_at:number;parts?:{position:number;body:string;status:string}[]}
defineProps<{items:Outreach[]}>()
const states:Record<string,string>={pending:'等待合适时机',evaluating:'正在想聊什么',sending:'正在发送',sent:'已送达',skip:'安静待着',cancelled:'已取消',failed:'未完成',unknown:'发送结果待核实'}
const reasons:Record<string,string>={new_message:'收到新消息，取消这次补充',new_reply:'已经有新的回复',settings_changed:'设置已修改',nothing_to_share:'没有值得补充的新内容',chat_cooldown:'刚聊过，留一点空间',outside_active_hours:'不在活动时段',quiet_hours:'免打扰时段',calendar_busy:'日程忙碌',awaiting_reply:'上一条还没人接话',daily_limit:'已达到消息上限',min_interval:'离上一次开场还不够久',no_context:'还没有可参考的近期聊天',stale_context:'近期没有互动',expired:'这次机会已过期',disabled:'功能已关闭',decision_limit:'今天已判断过多次',duplicate:'这句话已经分享过',processing_error:'处理未完成，请检查任务记录',interrupted:'处理中断，未自动重发',sharing:'有一点新内容想分享'}
</script>
<template><section class="panel spaced"><div class="section-heading"><div><h2>补充与主动开场</h2><p>看看聊了什么，或为什么选择安静。</p></div></div><p v-if="!items.length" class="muted">还没有记录。开启后，会按设定节奏判断。</p><article v-for="a in items" :key="a.id" class="qq-message"><div class="section-heading"><strong>{{a.kind==='followup'?'延迟补充':'主动开场'}}</strong><span class="tag lilac">{{states[a.status]||a.status}}</span></div><p v-if="a.body">{{a.body}}</p><div v-if="a.parts?.length" class="qq-group-meta"><span v-for="p in a.parts" :key="p.position">第 {{p.position+1}} 条 · {{states[p.status]||p.status}}</span></div><small>{{a.status==='pending'?`计划检查 ${date(a.due_at)}`:date(a.created_at)}} · {{reasons[a.reason]||a.reason}}</small></article></section></template>
